local _, E = ...
local crest = "DRUID:restoration"
local active = {}
local driver
local update

local function free(entry)
    active[entry] = nil
    for _, texture in ipairs(entry.warmupTextures or {}) do
        texture:SetTexture(nil)
    end
    entry.warmupKey = nil
end

local function configure(entry, config)
    if entry.preview or entry.libraryPreview then return end
    local art = entry.restorationSegments
    if E.GetCrestBakeKey(config) ~= crest or not art or not art.animate
        or not entry.artworkSegmentsActive or not entry.frame:IsVisible() then
        if entry.warmupKey then free(entry) end
        return
    end
    local paths = E.RestorationOpeningPages[art.size]
    if not paths then return end
    local state = entry.desktopCustom
    if entry.warmupKey == art.size and entry.warmupState == state then return end
    if entry.warmupKey ~= art.size then free(entry) end
    entry.warmupKey, entry.warmupState = art.size, state
    active[entry] = { paths = paths, index = 1, receiver = 0, effect = 1, state = state }
    if not driver then
        driver = CreateFrame("Frame")
        driver:SetScript("OnUpdate", function()
            for target, job in pairs(active) do
                if not target.frame:IsVisible() or not target.artworkSegmentsActive then
                    free(target)
                elseif not InCombatLockdown() and E.ActiveClass() == "DRUID" then
                    update(target, job)
                    break
                end
            end
            if not next(active) then driver:Hide() end
        end)
    end
    driver:Show()
end

update = function(entry, job)
    local textures = entry.warmupTextures or {}
    entry.warmupTextures = textures
    -- Limit overlapping texture requests and keep moving if readiness is unavailable.
    local pending = textures[job.index - 1]
    local ready = not pending or not pending.IsObjectLoaded or pending:IsObjectLoaded()
    local path = (ready or GetTime() >= job.nextRequest) and job.paths[job.index]
    if path then
        local texture = textures[job.index]
        if not texture then
            texture = entry.frame:CreateTexture()
            texture:SetPoint("TOPLEFT")
            texture:SetSize(1, 1)
            texture:SetAlpha(0)
            if texture.SetBlockingLoadsRequested then texture:SetBlockingLoadsRequested(false) end
            textures[job.index] = texture
        end
        texture:SetTexture(path)
        job.nextRequest = GetTime() + .05
        job.index = job.index + 1
    end
    -- Spread construction across updates too. These paths only allocate objects.
    if job.receiver and E.PrepareRestorationReceiver then
        job.receiver = E.PrepareRestorationReceiver(entry, job.receiver)
    end
    local key = job.state and job.state.ordered[job.effect]
    if key and entry.desktopCustom == job.state then
        E.PrepareRestorationEffect(entry, job.state.drivers[key])
        job.effect = job.effect + 1
    else
        job.effect = math.huge
    end
    if not job.paths[job.index] and not job.receiver and job.effect == math.huge then active[entry] = nil end
end

local apply, stop = E.UpdateEffects, E.StopEffects
function E.UpdateEffects(entry, config)
    local result = apply(entry, config)
    configure(entry, config)
    return result
end
function E.StopEffects(entry)
    if entry.warmupKey then free(entry) end
    return stop(entry)
end
